# @usage   : check interactions generated by interaction_detect.py

import pickle
import os
from Bio.Data import IUPACData
from Bio.PDB.MMCIF2Dict import MMCIF2Dict
import pandas as pd
pd.set_option('display.max_columns', 20)
pd.set_option('display.width', 180)
import re

# model_path requires structure with cif format
model_path = '~/8Y9N.cif'

cif_dict = MMCIF2Dict(model_path)
cif_info = {
    "model_num": cif_dict['_atom_site.pdbx_PDB_model_num'],
    "atom_level": cif_dict['_atom_site.group_PDB'],
    "atom_idx": cif_dict['_atom_site.id'],
    "seq_id": cif_dict['_atom_site.label_seq_id'],
    "seq_id_vis": cif_dict['_atom_site.auth_seq_id'],
    "chain_id": cif_dict['_atom_site.label_asym_id'],
    "atom_symbol": cif_dict['_atom_site.type_symbol'],
    "atom_label": cif_dict['_atom_site.label_atom_id'],
    "residue_name": cif_dict['_atom_site.label_comp_id']
}

df = pd.DataFrame(cif_info)

# result_file is the pkl file generated by interaction_detect.py
result_file = 'result.pkl'
result = {}
with open(result_file, 'rb') as h:
    result_part = pickle.load(h)
    for res in result_part:
        param = res.pop('param')
        if len(res) == 0:
            continue
        for k, v in res.items():
            assert k not in result.keys()
            result[k] = v

resi_polar = []
error = []
for k in result.keys():
    s,q = k.split('-')
    df_pair = df[df.atom_idx.isin([s,q])]
    if df_pair.chain_id.shape[0] != 2 or df_pair.chain_id.unique().tolist().__len__() != 2:
        error.append(k)
        continue
    df_resi = df_pair.loc[df_pair.chain_id=='A'].iloc[0,:].tolist()
    _, _, _, seq_id, _, chain_id, _, _, residue_name = df_resi
    residue_name = residue_name[0]+residue_name[-2:].lower()
    residue = IUPACData.protein_letters_3to1[residue_name]
    if f"{residue}{int(seq_id)}" in resi_polar:
        continue
    resi_polar.append(f"{residue}{int(seq_id)}")
#
resi_polar = sorted(resi_polar, key=lambda x: int(x[1:]))
print(resi_polar)
